#Requires -Version 5.1
# fix-android-createElement.ps1
# Fix definitivo para Android Chrome:
# - document.createElement("input") + appendChild + click()
# - El input se añade al DOM antes del click (necesario en Android)
# - Se elimina del DOM en el onchange (cleanup)
# - Esto garantiza que Android Chrome reconoce el evento como gesto del usuario

$ErrorActionPreference = "Stop"
$RepoPath = "C:\Users\lauro\Desktop\LOYNEK\ObrasPlan\obrasplan-mvp\obrasplan"
if (-not (Test-Path $RepoPath)) { Write-Host "ERROR" -ForegroundColor Red; exit 1 }
Set-Location $RepoPath
git pull --quiet 2>$null
Write-Host "" ; Write-Host "==> Fix Android createElement" -ForegroundColor Cyan

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path $RepoPath "src\app\partes\[id]\page.tsx"), $bytes)

$c = [System.IO.File]::ReadAllText((Join-Path $RepoPath "src\app\partes\[id]\page.tsx"), [System.Text.Encoding]::UTF8)
if ($c.Contains("appendChild")) { Write-Host "  OK: appendChild presente" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($c.Contains("removeChild")) { Write-Host "  OK: removeChild presente" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if ($c.Contains("obraIdSnapshot")) { Write-Host "  OK: obraIdSnapshot (no borra obra)" -ForegroundColor Green } else { Write-Host "  ERROR" -ForegroundColor Red }
if (-not $c.Contains("parte-file-input")) { Write-Host "  OK: sin input estatico" -ForegroundColor Green } else { Write-Host "  WARN" -ForegroundColor Yellow }

Write-Host ""
Write-Host '  git add "src\app\partes\[id]\page.tsx"'
Write-Host '  git commit -m "fix: Android upload - createElement + appendChild antes del click"'
Write-Host '  git push'
